def solve(s: str) -> bool:
    """Return True if s is a valid IPv4 address.
    Conditions:
    - Four decimal numbers separated by '.'
    - Each number between 0 and 255 inclusive
    - No leading zeros unless the number is exactly '0'
    - Only digits in each part
    """
    # Split by '.'
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # Non-empty
        if not part:
            return False
        # All digits
        if not part.isdigit():
            return False
        # No leading zeros (except single '0')
        if len(part) > 1 and part[0] == '0':
            return False
        # Range check
        try:
            num = int(part)
        except ValueError:
            return False
        if not (0 <= num <= 255):
            return False
    return True

