    """Compute the determinant of an integer square matrix.
    - If called with a single argument (the matrix as list of lists), returns the determinant.
    - If called with no arguments, reads a Python literal from stdin, evaluates it, computes the determinant, prints and returns it.
    An empty matrix (i.e., []) or a matrix with no columns (e.g., [[]]) has determinant 1.
    """
    import sys
    def determinant(mat):
        # Empty matrix or matrix with zero columns
        if not mat:
            return 1
        if len(mat) == 1 and not mat[0]:  # [[]]
            return 1
        n = len(mat)
        # Verify square matrix
        for row in mat:
            if len(row) != n:
                raise ValueError("Matrix must be square")
        # Deep copy to avoid mutating input
        A = [list(row) for row in mat]
        sign = 1
        # Bareiss algorithm (fraction‑free Gaussian elimination)
        for k in range(n - 1):
            # Pivot handling: if pivot is zero, swap with a lower row that has non‑zero entry
            if A[k][k] == 0:
                swap_row = None
                for i in range(k + 1, n):
                    if A[i][k] != 0:
                        swap_row = i
                        break
                if swap_row is None:
                    return 0  # Singular matrix
                A[k], A[swap_row] = A[swap_row], A[k]
                sign = -sign
            pivot = A[k][k]
            prev_pivot = A[k - 1][k - 1] if k > 0 else 1
            for i in range(k + 1, n):
                for j in range(k + 1, n):
                    # Exact integer arithmetic; division is exact by properties of Bareiss
                    A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
                A[i][k] = 0
        det = sign * A[n - 1][n - 1]
        return det

    if args:
        matrix = args[0]
        return determinant(matrix)
    else:
        data = sys.stdin.read().strip()
        if not data:
            return
        try:
            matrix = eval(data, {"__builtins__": {}})
        except Exception:
            # Fallback: parse lines of space‑separated integers
            lines = data.splitlines()
            matrix = [list(map(int, line.split())) for line in lines if line.strip()]
        result = determinant(matrix)
        print(result)
        return result
