    """Return length of longest strictly increasing subsequence.
    Uses patience sorting (O(n log n)). If elements are not comparable,
    falls back to returning 1 for non‑empty input (any single element trivially
    forms an increasing subsequence) or 0 for empty input.
    """
    if not arr:
        return 0
