            i = bisect.bisect_left(dp, x)
            if i == len(dp):
                dp.append(x)
            else:
                dp[i] = x
        return len(dp)
    except Exception:
        # If comparison fails (e.g., unorderable types), the longest strictly
        # increasing subsequence can be at most 1 (any single element).
        return 1
