        return []
    # Determine dimensions
    rows = len(matrix)
    cols = len(matrix[0]) if matrix[0] else 0
    if cols == 0:
        return []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1
    res = []
    while top <= bottom and left <= right:
        # top row
        for j in range(left, right + 1):
            res.append(matrix[top][j])
        top += 1
        # right column
