def solve(grid):
    """Count number of islands (connected components of 1s) in a 2D grid.
    Connectivity is 4-directional (up, down, left, right).
    Returns 0 for empty grid.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if cols == 0:
        return 0
    visited = [[False] * cols for _ in range(rows)]
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                # DFS stack
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    x, y = stack.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            if grid[nx][ny] == 1 and not visited[nx][ny]:
                                visited[nx][ny] = True
                                stack.append((nx, ny))
    return count

