def solve(a, x):
    """Return the leftmost index where ``x`` can be inserted into the sorted
    sequence ``a`` to maintain sorted order (equivalent to ``bisect_left``).
    Works for any sequence that supports ``len`` and indexing. If elements are
    not comparable with ``x``, falls back to a linear scan using equality.
    """
    # Fast path: binary search when comparison works
    try:
        lo, hi = 0, len(a)
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo
    except Exception:
        # Fallback: linear scan to find first element that is equal to x
        for i, val in enumerate(a):
            try:
                if val == x:
                    return i
            except Exception:
                continue
        # If x not found, insertion point is at the end
        return len(a)

