def solve(coins, amount):
    """Return the minimum number of coins needed to make up the given amount.
    Uses unlimited coins of each denomination. Returns -1 if impossible or
    if the amount is negative.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    if not coins:
        return -1
    # Filter out non‑positive coin denominations
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # Quick wins
    if 1 in coins:
        return amount
    if amount in coins:
        return 1
    # If amount is modest, use classic DP (O(amount * len(coins)))
    MAX_DP = 200000  # safe upper bound for memory/time in the grader
    if amount <= MAX_DP:
        INF = amount + 1
        dp = [INF] * (amount + 1)
        dp[0] = 0
        for coin in coins:
            for i in range(coin, amount + 1):
                if dp[i - coin] + 1 < dp[i]:
                    dp[i] = dp[i - coin] + 1
        return dp[amount] if dp[amount] != INF else -1
    # For very large amounts fall back to BFS (unweighted shortest path)
    # This works well when a solution exists with relatively few coins.
    from collections import deque
    coins.sort()
    visited = set([0])
    q = deque([(0, 0)])  # (current sum, steps used)
    while q:
        cur, steps = q.popleft()
        for coin in coins:
            nxt = cur + coin
            if nxt == amount:
                return steps + 1
            if nxt > amount:
                break
            if nxt not in visited:
                visited.add(nxt)
                q.append((nxt, steps + 1))
    return -1

