    Uses DP with time O(amount * len(coins))."""
    if amount < 0:
        return -1
    # Initialize DP array where dp[i] = min coins for amount i
    # Use a large sentinel value larger than any possible answer
    INF = amount + 1  # more than max possible coins (using 1-coin)
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If we can use coin c, consider using it
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

